<?php
namespace Tests\Unit;
use App\Services\Trading\PositionManagementReferenceSelectionPolicyService;
use Tests\TestCase;
class PositionManagementReferenceSelectionPolicyServiceTest extends TestCase
{protected function policy($over=[]){return array_replace_recursive(['schema_version'=>'trading_position_management_reference_selection_policy_v1','status'=>'reference_only','policy_id'=>'p','policy_version'=>'v','selection_scope'=>'management_action_reference','selection_mode'=>'single_proposal_reference','portfolio_id'=>'pf','position_id'=>'pos','management_candidate_id'=>'mc','action_plan_id'=>'plan','management_approval_id'=>'ap','proposed_management_action'=>'exit_position','proposed_quantity_reference'=>1000,'requirements'=>['management_candidate_valid'=>true,'action_plan_materialized'=>true,'management_reference_approved'=>true],'source'=>['type'=>'synthetic_test_fixture','identifier'=>'x'],'approved_for_reference_selection'=>true,'approved_for_production_selection'=>false,'approved_for_execution'=>false],$over);}protected function ctx($p=null){return ['management_reference_selection_policy'=>$p??$this->policy(),'management_candidate'=>['status'=>'policy_hypothesis','candidate_id'=>'mc'],'action_plan'=>['status'=>'materialized_reference','position_id'=>'pos','action_plan_id'=>'plan','proposed_management_action'=>'exit_position','quantity_plan'=>['proposed_quantity_reference'=>1000]],'management_portfolio_approval'=>['portfolio_id'=>'pf','status'=>'approved_reference']];}
 public function test_unavailable_invalid_mismatch_and_eligible():void{$svc=new PositionManagementReferenceSelectionPolicyService();$this->assertSame('unavailable',$svc->evaluate([])['status']);$this->assertSame('invalid',$svc->evaluate($this->ctx($this->policy(['schema_version'=>'x'])))['status']);$this->assertSame('blocked',$svc->evaluate($this->ctx($this->policy(['action_plan_id'=>'x'])))['status']);$this->assertSame('eligible_for_reference_selection',$svc->evaluate($this->ctx())['status']);}
 public function test_denied_unknown_and_reduction():void{$svc=new PositionManagementReferenceSelectionPolicyService();$this->assertSame('denied_reference_selection',$svc->evaluate($this->ctx($this->policy(['approved_for_reference_selection'=>false])))['status']);$this->assertSame('invalid',$svc->evaluate($this->ctx($this->policy(['requirements'=>['unknown'=>true]])))['status']);$p=$this->policy(['proposed_management_action'=>'reduce_position','proposed_quantity_reference'=>500]);$c=$this->ctx($p);$c['action_plan']['proposed_management_action']='reduce_position';$c['action_plan']['quantity_plan']['proposed_quantity_reference']=500;$this->assertSame('eligible_for_reference_selection',$svc->evaluate($c)['status']);}}
